  notice=new TextView(this);notice.setTextSize(12);notice.setTextColor(0xff626970);notice.setSingleLine(true);notice.setEllipsize(android.text.TextUtils.TruncateAt.END);notice.setPadding(dp(4),dp(5),dp(4),dp(5));if(font!=null)notice.setTypeface(font);root.addView(notice);search=new EditText(this);search.setSingleLine(true);search.setHint("Hat, durak veya istasyon ara");search.setTextSize(14);search.setTextColor(0xff171b1f);search.setHintTextColor(0xff646c74);search.setPadding(dp(12),dp(6),dp(12),dp(6));if(font!=null)search.setTypeface(font);search.setBackgroundDrawable(surface(0xffffffff,0xffcdd3da));root.addView(search,new LinearLayout.LayoutParams(-1,dp(44)));
  LinearLayout tabs=new LinearLayout(this);root.addView(tabs);addButton(tabs,"Hatlar",new View.OnClickListener(){public void onClick(View v){mode=0;page=0;show();}});addButton(tabs,"Duraklar",new View.OnClickListener(){public void onClick(View v){mode=1;page=0;show();}});addButton(tabs,"Favori",new View.OnClickListener(){public void onClick(View v){mode=2;page=0;show();}});
  list=new ListView(this);list.setCacheColorHint(0xffffffff);list.setDivider(new android.graphics.drawable.ColorDrawable(0xffedf0f3));list.setDividerHeight(dp(1));list.setBackgroundColor(0xffffffff);root.addView(list,new LinearLayout.LayoutParams(-1,0,1));list.setOnItemClickListener(new AdapterView.OnItemClickListener(){public void onItemClick(AdapterView<?> a,View v,int pos,long id){detail(rows.get(pos));}});list.setOnItemLongClickListener(new AdapterView.OnItemLongClickListener(){public boolean onItemLongClick(AdapterView<?> a,View v,int pos,long id){favorite(rows.get(pos));return true;}});
  LinearLayout nav=new LinearLayout(this);root.addView(nav);addButton(nav,"‹",new View.OnClickListener(){public void onClick(View v){if(page>0){page--;show();}}});pages=new TextView(this);pages.setTextSize(12);pages.setTextColor(0xff626970);pages.setGravity(android.view.Gravity.CENTER);if(font!=null)pages.setTypeface(font);nav.addView(pages,new LinearLayout.LayoutParams(0,-2,2));addButton(nav,"›",new View.OnClickListener(){public void onClick(View v){if(rows.size()==50){page++;show();}}});
  LinearLayout tools=new LinearLayout(this);root.addView(tools);addButton(tools,"Yakınımda",new View.OnClickListener(){public void onClick(View v){nearDialog();}});addButton(tools,"Asistan",new View.OnClickListener(){public void onClick(View v){assistant();}});addButton(tools,"Resmî",new View.OnClickListener(){public void onClick(View v){officialDialog();}});
  root.removeView(nav);View previous=nav.getChildAt(0);View next=nav.getChildAt(nav.getChildCount()-1);nav.removeView(previous);nav.removeView(next);tabs.addView(previous,new LinearLayout.LayoutParams(0,dp(42),.55f));tabs.addView(next,new LinearLayout.LayoutParams(0,dp(42),.55f));previous.setContentDescription("Önceki sayfa");next.setContentDescription("Sonraki sayfa");setContentView(root);root.requestFocus();city.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onItemSelected(AdapterView<?> a,View v,int i,long id){page=0;getPreferences(0).edit().putInt("city",i).commit();show();}public void onNothingSelected(AdapterView<?> a){}});
